function signedReceipt({ manifestDigest, resultCoreDigest, contractDigest, issuerId, trustDomain, evidenceClass, keyPurpose }) {
  const { publicKey, privateKey } = crypto.generateKeyPairSync("ed25519");
  const signerKeyId = digestBytes(publicKey.export({ type: "spki", format: "der" }));
  const receipt = {
    receiptSchemaVersion: "authored-semantic-validation-receipt/v1", issuerId, signerKeyId,
    signatureAlgorithm: "Ed25519", signatureBase64: "", issuedAt: new Date(Date.now() - 1000).toISOString(),
    expiresAt: new Date(Date.now() + 30 * 60 * 1000).toISOString(), nonce: crypto.randomBytes(24).toString("hex"),
    subjectManifestDigest: manifestDigest, subjectResultCoreDigest: resultCoreDigest,
    semanticValidatorContractDigest: contractDigest, receiptDigest: "",
  };
  receipt.receiptDigest = canonicalSha256Excluding(receipt, ["$.receiptDigest", "$.signatureBase64"]);
  receipt.signatureBase64 = crypto.sign(null, Buffer.from(receipt.receiptDigest, "ascii"), privateKey).toString("base64");
  return { receipt, attestation: { schemaVersion: "test-attestation/v1", trustDomain, authorityDomain: trustDomain === "gate_minus1_actual_probe" ? undefined : "actual_product", evidenceClass, keyPurpose, issuerId, signerKeyId, publicKeySpkiBase64: publicKey.export({ type: "spki", format: "der" }).toString("base64"), privateKeyPersisted: false, revoked: false } };
}

function makeGateMinus1(temp) {
  const contractPath = path.join(contracts, "gate-minus1-semantic-validator-contract.v1.json");
  const contract = JSON.parse(fs.readFileSync(contractPath, "utf8"));
  const manifest = { schemaVersion: "test-gate-minus1-manifest/v1", cases: Array.from({ length: 18 }, (_, index) => ({ ordinal: index + 1, caseId: `gm1.${index + 1}` })), manifestDigest: "" };
  manifest.manifestDigest = canonicalSha256Excluding(manifest, ["$.manifestDigest"]);
  const result = { schemaVersion: "authored-gate-minus1-result-set/v1", suiteStatus: "feasible", executedCaseCount: 18, skippedCaseCount: 0, manifestDigest: manifest.manifestDigest, resultCoreDigest: "", semanticValidationReceiptRef: null, resultSetDigest: "" };
  result.resultCoreDigest = canonicalSha256Excluding(result, ["$.resultCoreDigest", "$.semanticValidationReceiptRef", "$.resultSetDigest"]);
  const signed = signedReceipt({ manifestDigest: manifest.manifestDigest, resultCoreDigest: result.resultCoreDigest, contractDigest: contract.contractDigest, issuerId: "gate-minus1-actual-probe/test", trustDomain: "gate_minus1_actual_probe" });
  const manifestPath = path.join(temp, "gate-minus1-manifest.json");
  const resultPath = path.join(temp, "gate-minus1-result.json");
  const receiptPath = path.join(temp, "gate-minus1-receipt.json");
  const attestationPath = path.join(temp, "gate-minus1-attestation.json");
  writeJson(manifestPath, manifest); writeJson(receiptPath, signed.receipt); writeJson(attestationPath, signed.attestation);
  const receiptBytes = fs.readFileSync(receiptPath);
  result.semanticValidationReceiptRef = { sha256: digestBytes(receiptBytes) };
  result.resultSetDigest = canonicalSha256Excluding(result, ["$.resultSetDigest"]);
  writeJson(resultPath, result);
  return { manifestPath, resultPath, receiptPath, attestationPath, contractPath, manifest, result, receiptArtifactDigest: digestBytes(receiptBytes), contract };
}

function ledgerCells(manifest) {
  const cells = [];
  for (let slideNumber = 1; slideNumber <= 8; slideNumber += 1) for (const exportMode of manifest.manualLedgerAxes.exportModes) for (const comPhase of manifest.manualLedgerAxes.comPhases) for (const defectFieldId of manifest.requiredDefectFieldIds) { const number = String(slideNumber).padStart(2, "0"); cells.push({ slideNumber, exportMode, comPhase, defectFieldId, state: "accepted", evidenceArtifactIds: [`${exportMode}-browser-slide-${number}-png`, `${exportMode}-${comPhase}-slide-${number}-png`, `${exportMode}-${comPhase}-com-json`] }); }
  return cells;
}

function pngBytes(width = 1280, height = 720) {
  const chunk = (type, data) => { const result = Buffer.alloc(12 + data.length); result.writeUInt32BE(data.length, 0); result.write(type, 4, 4, "ascii"); data.copy(result, 8); return result; };
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(width, 0); ihdr.writeUInt32BE(height, 4); ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((width * 4 + 1) * height);
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk("IHDR", ihdr), chunk("IDAT", zlib.deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]);
}

function visualComparisonTuples() {
  const result = [];
  for (let slide = 1; slide <= 8; slide += 1) { const number = String(slide).padStart(2, "0"); for (const mode of ["fidelity", "hybrid"]) { result.push([`${mode}-source-vs-first-${number}`, `${mode}-browser-slide-${number}-png`, `${mode}-first-open-slide-${number}-png`]); result.push([`${mode}-source-vs-reopen-${number}`, `${mode}-browser-slide-${number}-png`, `${mode}-reopen-slide-${number}-png`]); result.push([`${mode}-first-vs-reopen-${number}`, `${mode}-first-open-slide-${number}-png`, `${mode}-reopen-slide-${number}-png`]); } result.push([`hybrid-vs-fidelity-first-${number}`, `fidelity-first-open-slide-${number}-png`, `hybrid-first-open-slide-${number}-png`]); result.push([`hybrid-vs-fidelity-reopen-${number}`, `fidelity-reopen-slide-${number}-png`, `hybrid-reopen-slide-${number}-png`]); }
  return result;
}

