  assert.equal(core.artifactInventory.length, 70);
  assert.equal(core.ledgerCellCount, 384);
  assert.equal(core.notVerifiedPhaseCount, 5);
  assert.equal(core.acceptedPhaseCount, 32);

  const receiptPath = path.join(fixture.temp, "gate1-receipt.json");
  writeJson(receiptPath, fixture.semanticSigner.issue(core));
  const final = sealGate1({ resultCorePath: path.join(outputDir, "gate1-result-core.json"), receiptPath, trustAttestationPath: fixture.semanticSigner.trustPath, serverReadbackVerifierAttestationPath: fixture.serverReadbackVerifierAttestationPath, releaseTrustReadbackPath: fixture.releaseTrustReadbackPath, resultPath: path.join(outputDir, "gate1-result-set.json") });
  assert.equal(final.suiteStatus, "not-verified");
