  const semanticTrust = JSON.parse(fs.readFileSync(fixture.semanticSigner.trustPath, "utf8")); semanticTrust.environmentId = "different-environment"; writeJson(fixture.semanticSigner.trustPath, semanticTrust);
  assert.throws(() => sealGate1({ resultCorePath: path.join(outputDir, "gate1-result-core.json"), receiptPath, trustAttestationPath: fixture.semanticSigner.trustPath, serverReadbackVerifierAttestationPath: fixture.serverReadbackVerifierAttestationPath, releaseTrustReadbackPath: fixture.releaseTrustReadbackPath, resultPath: path.join(outputDir, "gate1-result-set-trust-mutated.json") }), /gate1-semantic-validator-trust-digest-mismatch/);

  const bindings = JSON.parse(fs.readFileSync(fixture.bindingsPath, "utf8")); const observations = JSON.parse(fs.readFileSync(fixture.observationsPath, "utf8"));
  const sourceMapPath = path.join(fixture.temp, "actual-source-map.json"); const manualPath = path.join(fixture.temp, "manual-observations.json");
  writeJson(sourceMapPath, { schemaVersion: "authored-gate1-actual-artifact-source-map/v1", authorityDomain: "actual_product", presentationId: fixture.pins.presentationId, presentationRevision: fixture.pins.presentationRevision, generationAttemptId: fixture.pins.generationAttemptId, fidelityExportAttemptId: fixture.pins.fidelityExportAttemptId, hybridExportAttemptId: fixture.pins.hybridExportAttemptId, artifacts: bindings.artifacts.filter((entry) => entry.artifactId !== "manual-ledger-json").map((entry) => ({ ...entry, path: path.join(fixture.bundle, entry.locator) })), phaseEvidence: observations.phases.map((entry) => ({ phaseId: entry.phaseId, ordinal: entry.ordinal, observedState: entry.state, evidenceArtifactIds: entry.evidenceArtifactIds })) });
  const ledger = JSON.parse(fs.readFileSync(path.join(fixture.bundle, "manual-ledger-json.json"), "utf8"));
  writeJson(manualPath, { schemaVersion: "authored-gate1-manual-observations/v1", authorityDomain: "actual_product", presentationId: fixture.pins.presentationId, presentationRevision: fixture.pins.presentationRevision, generationAttemptId: fixture.pins.generationAttemptId, fidelityExportAttemptId: fixture.pins.fidelityExportAttemptId, hybridExportAttemptId: fixture.pins.hybridExportAttemptId, cells: ledger.cells });
  assert.deepEqual(assembleGate1Bundle({ manifestPath: path.join(contracts, "gate1-phase-manifest.v1.json"), artifactSourceMapPath: sourceMapPath, manualObservationsPath: manualPath, bundleDir: path.join(fixture.temp, "assembled-bundle"), outputDir: path.join(fixture.temp, "assembled-control") }), { artifactCount: 70, phaseCount: 37, ledgerCellCount: 384 });
  const inventedRootPath = path.join(fixture.temp, "invented-root.json"); const rootProvenance = JSON.parse(fs.readFileSync(path.join(fixture.bundle, "evidence-graph-root-json.json"), "utf8")); writeJson(inventedRootPath, rootProvenance.create.request); const inventedBytes = fs.readFileSync(inventedRootPath);
  const bypassSourceMap = structuredClone(JSON.parse(fs.readFileSync(sourceMapPath, "utf8"))); const rootSource = bypassSourceMap.artifacts.find((entry) => entry.artifactId === "evidence-graph-root-json"); rootSource.path = inventedRootPath; rootSource.sha256 = digestBytes(inventedBytes); rootSource.byteLength = inventedBytes.length; const bypassSourceMapPath = path.join(fixture.temp, "bypass-source-map.json"); writeJson(bypassSourceMapPath, bypassSourceMap);
  assert.throws(() => assembleGate1Bundle({ manifestPath: path.join(contracts, "gate1-phase-manifest.v1.json"), artifactSourceMapPath: bypassSourceMapPath, manualObservationsPath: manualPath, bundleDir: path.join(fixture.temp, "bypass-assembled-bundle"), outputDir: path.join(fixture.temp, "bypass-assembled-control") }), /gate1-fastapi-root-provenance-required/);
  const inventedCompletionPath = path.join(fixture.temp, "invented-completion.json"); const completionProvenance = JSON.parse(fs.readFileSync(path.join(fixture.bundle, "completion-seal-json.json"), "utf8")); writeJson(inventedCompletionPath, completionProvenance.create.response); const inventedCompletionBytes = fs.readFileSync(inventedCompletionPath); const completionBypassSourceMap = structuredClone(JSON.parse(fs.readFileSync(sourceMapPath, "utf8"))); const completionSource = completionBypassSourceMap.artifacts.find((entry) => entry.artifactId === "completion-seal-json"); completionSource.path = inventedCompletionPath; completionSource.sha256 = digestBytes(inventedCompletionBytes); completionSource.byteLength = inventedCompletionBytes.length; const completionBypassSourceMapPath = path.join(fixture.temp, "completion-bypass-source-map.json"); writeJson(completionBypassSourceMapPath, completionBypassSourceMap);
  assert.throws(() => assembleGate1Bundle({ manifestPath: path.join(contracts, "gate1-phase-manifest.v1.json"), artifactSourceMapPath: completionBypassSourceMapPath, manualObservationsPath: manualPath, bundleDir: path.join(fixture.temp, "completion-bypass-assembled-bundle"), outputDir: path.join(fixture.temp, "completion-bypass-assembled-control") }), /gate1-fastapi-completion-provenance-required/);
  const staleManualPath = path.join(fixture.temp, "stale-manual-observations.json"); writeJson(staleManualPath, { ...JSON.parse(fs.readFileSync(manualPath, "utf8")), cells: ledger.cells.map((cell) => ({ ...cell, reviewedAt: "2000-01-01T00:00:00.000Z" })) });
  assert.throws(() => assembleGate1Bundle({ manifestPath: path.join(contracts, "gate1-phase-manifest.v1.json"), artifactSourceMapPath: sourceMapPath, manualObservationsPath: staleManualPath, bundleDir: path.join(fixture.temp, "stale-assembled-bundle"), outputDir: path.join(fixture.temp, "stale-assembled-control") }), /gate1-manual-observation-unreviewed/);

  fs.appendFileSync(path.join(fixture.bundle, "semantic-source-json.json"), "tamper");
