integrationTest("Gate 1 rejects mixed attempts, stale or nonce-mismatched readbacks, and bare ledgers", () => {
  const fixture = buildFixture();
  const rootPath = path.join(fixture.bundle, "evidence-graph-root-json.json"); const originalRoot = JSON.parse(fs.readFileSync(rootPath, "utf8"));
  const mixedRoot = structuredClone(originalRoot); const mixedRequest = structuredClone(mixedRoot.create.request); delete mixedRequest.authority; mixedRequest.presentationId = "00000000-0000-4000-8000-000000000099"; mixedRoot.create.request = fixture.productSigner.issue(mixedRequest); refreshExchange(mixedRoot.create);
  rewriteBoundArtifact(fixture, "evidence-graph-root-json", mixedRoot);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "mixed-attempt-evidence"))), /gate1-evidence-root-request-digest-mismatch/);

  rewriteBoundArtifact(fixture, "evidence-graph-root-json", originalRoot);
  const completionPath = path.join(fixture.bundle, "completion-seal-json.json"); const originalCompletion = JSON.parse(fs.readFileSync(completionPath, "utf8")); const mutatedCompletion = structuredClone(originalCompletion); mutatedCompletion.create.request.requiredCapabilityIds = mutatedCompletion.create.request.requiredCapabilityIds.slice(1); refreshExchange(mutatedCompletion.create); rewriteBoundArtifact(fixture, "completion-seal-json", mutatedCompletion);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "mutated-capability-evidence"))), /gate1-completion-create-response-invalid/);

  rewriteBoundArtifact(fixture, "completion-seal-json", originalCompletion);
  const truncatedInventoryRoot = structuredClone(originalRoot); const truncatedRequest = structuredClone(truncatedInventoryRoot.create.request); delete truncatedRequest.authority; truncatedRequest.finalRequiredArtifactIdsDigest = `sha256:${"0".repeat(64)}`; truncatedRequest.rootDigest = ""; truncatedRequest.rootDigest = canonicalSha256Excluding(truncatedRequest, ["$.rootDigest", "$.authority"]); truncatedInventoryRoot.create.request = fixture.productSigner.issue(truncatedRequest); truncatedInventoryRoot.create.response.finalRequiredArtifactIdsDigest = truncatedRequest.finalRequiredArtifactIdsDigest; truncatedInventoryRoot.create.response.rootDigest = truncatedRequest.rootDigest; const unsignedTruncatedRequest = structuredClone(truncatedInventoryRoot.create.request); delete unsignedTruncatedRequest.authority; truncatedInventoryRoot.create.response.requestDigest = canonicalSha256Excluding(unsignedTruncatedRequest, []); truncatedInventoryRoot.readback.response = fixture.readbackSigner.sign(truncatedInventoryRoot.create.response); refreshExchange(truncatedInventoryRoot.create); refreshExchange(truncatedInventoryRoot.readback); rewriteBoundArtifact(fixture, "evidence-graph-root-json", truncatedInventoryRoot);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "mutated-final-inventory-evidence"))), /gate1-evidence-root-inventory-digest-mismatch/);

  rewriteBoundArtifact(fixture, "evidence-graph-root-json", originalRoot);
  const corruptedComRoot = structuredClone(originalRoot); corruptedComRoot.comQualificationReadback.response.evidence.repairDialogs = 1; corruptedComRoot.comQualificationReadback.response = fixture.readbackSigner.sign(corruptedComRoot.comQualificationReadback.response); refreshExchange(corruptedComRoot.comQualificationReadback); rewriteBoundArtifact(fixture, "evidence-graph-root-json", corruptedComRoot);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "mutated-com-readback-evidence"))), /gate1-com-qualification-readback-invalid/);

  rewriteBoundArtifact(fixture, "evidence-graph-root-json", originalRoot);
  const staleRoot = structuredClone(originalRoot); const staleIssuedAt = new Date(Date.now() - 600_000).toISOString(); staleRoot.readback.response = fixture.readbackSigner.sign(staleRoot.readback.response, { issuedAt: staleIssuedAt, expiresAt: new Date(Date.parse(staleIssuedAt) + 300_000).toISOString() }); refreshExchange(staleRoot.readback); rewriteBoundArtifact(fixture, "evidence-graph-root-json", staleRoot);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "stale-readback-evidence"))), /gate1-evidence-root-server-readback-freshness-invalid/);

  rewriteBoundArtifact(fixture, "evidence-graph-root-json", originalRoot);
  const wrongNonceCompletion = structuredClone(originalCompletion); wrongNonceCompletion.readback.response = fixture.readbackSigner.sign(wrongNonceCompletion.readback.response, { executionNonce: "different-gate1-execution-nonce" }); refreshExchange(wrongNonceCompletion.readback); rewriteBoundArtifact(fixture, "completion-seal-json", wrongNonceCompletion);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "nonce-mismatch-readback-evidence"))), /gate1-completion-server-readback-freshness-invalid/);

  rewriteBoundArtifact(fixture, "completion-seal-json", originalCompletion);
  const ledgerPath = path.join(fixture.bundle, "manual-ledger-json.json"); const originalLedger = JSON.parse(fs.readFileSync(ledgerPath, "utf8")); rewriteBoundArtifact(fixture, "manual-ledger-json", originalLedger.cells);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "bare-ledger-evidence"))), /gate1-ledger-envelope-(?:schema-fields-)?invalid/);
  rewriteBoundArtifact(fixture, "manual-ledger-json", originalLedger);

  const originalReadback = fs.readFileSync(fixture.releaseTrustReadbackPath); const forgedTrustReadback = JSON.parse(originalReadback.toString("utf8")); forgedTrustReadback.readback.response.registeredKeys = forgedTrustReadback.readback.response.registeredKeys.slice(1); forgedTrustReadback.readback.response = fixture.readbackSigner.sign(forgedTrustReadback.readback.response); refreshExchange(forgedTrustReadback.readback); writeJson(fixture.releaseTrustReadbackPath, forgedTrustReadback);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "operator-trust-evidence"))), /gate1-release-trust-readback-artifact-mismatch/);
  fs.writeFileSync(fixture.releaseTrustReadbackPath, originalReadback);

  const trust = JSON.parse(fs.readFileSync(fixture.productAuthorityTrustPath, "utf8")); trust.signerKeyId = "operator-substituted-key"; writeJson(fixture.productAuthorityTrustPath, trust);
  assert.throws(() => collectGate1(collectOptions(fixture, path.join(fixture.temp, "mutated-trust-evidence"))), /gate1-product-trust-bundle-digest-mismatch/);
});
